pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount < 1e30);

        // give the contract a fuzzed balance
        vm.deal(address(c), amount);

        // owner (this test contract) drains everything
        c.withdrawAll();

        // Rule: after withdrawAll, the contract's balance is strictly below 1 wei,
        // so an owner withdraw(1) must revert (insufficient balance).
        bool ok = false;
        try c.withdraw(1) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

