pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: contract holds a strictly positive (capped) ether balance.
        amount = bound(amount, 1 wei, 1e30);

        // Fund the contract directly (no payable entry needed for this difference).
        vm.deal(address(c), amount);

        // Owner (the deployer = this test contract) drains the contract.
        c.withdrawAll();

        // General rule: a full-balance withdrawal leaves the contract with
        // strictly less than 1 wei. The reference always satisfies this for
        // every admissible balance; the "balance - 1" mutant always leaves
        // exactly 1 wei behind and thus violates it for every admissible input.
        assertTrue(address(c).balance < 1 wei, "withdrawAll must drain the contract completely");
    }
}

