pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // wide admissible domain: fund the contract itself directly with the fuzzed amount
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;

        // setUp() deployed c, so owner == this test contract; call withdraw directly
        c.withdraw(amount);

        // Rule: an owner withdrawal of `amount` moves exactly `amount` out of the
        // contract to the caller, so the contract balance must drop by `amount`.
        // The mutant pays address(this) (the contract itself), leaving the balance
        // unchanged, breaking the rule whenever amount > 0.
        assertTrue(address(c).balance == before - amount);
    }
}

