contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address _target, uint _value, bytes memory _data) public {
        // In P, a failing low-level call causes require(...) to revert.
        // In M, the require is removed, so the call succeeds silently.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, _target, _value, _data));
        // If the target call fails, P reverts (ok == false); M does not.
        require(_thisCallFails(_target, _value, _data) == true || ok == true);
        assert(ok);
    }

    function _thisCallFails(address _target, uint _value, bytes memory _data) internal pure returns (bool) {
        return false;
    }
}

